class Solution:
    def minimumTime(self, hens: List[int], grains: List[int]) -> int:
        hens.sort(); grains.sort()
        m = len(grains)
        def ok(T):
            gi = 0
            for h in hens:
                if gi == m: break
                if grains[gi] >= h:
                    if grains[gi] - h > T: return False
                    r = h + T
                else:
                    d = h - grains[gi]
                    if d > T: return False
                    r = h + max(T - d, (T - d) // 2)
                while gi < m and grains[gi] <= r: gi += 1
            return gi == m
        lo, hi = 0, 2 * 10**9
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid): hi = mid
            else: lo = mid + 1
        return lo

