class Solution {
public:
    int minimumTime(vector<int>& hens, vector<int>& grains) {
        sort(hens.begin(), hens.end());
        sort(grains.begin(), grains.end());
        int m = grains.size();
        auto ok = [&](long long T) {
            int gi = 0;
            for (long long h : hens) {
                if (gi == m) break;
                long long r;
                if (grains[gi] >= h) {
                    if (grains[gi] - h > T) return false;
                    r = h + T;
                } else {
                    long long d = h - grains[gi];
                    if (d > T) return false;
                    r = h + max(T - d, (T - d) / 2);
                }
                while (gi < m && grains[gi] <= r) gi++;
            }
            return gi == m;
        };
        long long lo = 0, hi = 2e9;
        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            if (ok(mid)) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
};

