class Solution {
    public int minimumTime(int[] hens, int[] grains) {
        Arrays.sort(hens); Arrays.sort(grains);
        int m = grains.length;
        long lo = 0, hi = 2000000000L;
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            if (ok(hens, grains, mid)) hi = mid; else lo = mid + 1;
        }
        return (int) lo;
    }
    private boolean ok(int[] hens, int[] grains, long T) {
        int m = grains.length, gi = 0;
        for (long h : hens) {
            if (gi == m) break;
            long r;
            if (grains[gi] >= h) {
                if (grains[gi] - h > T) return false;
                r = h + T;
            } else {
                long d = h - grains[gi];
                if (d > T) return false;
                r = h + Math.max(T - d, (T - d) / 2);
            }
            while (gi < m && grains[gi] <= r) gi++;
        }
        return gi == m;
    }
}

