var minimumTime = function(hens, grains) {
    hens.sort((a, b) => a - b); grains.sort((a, b) => a - b);
    const m = grains.length;
    const ok = (T) => {
        let gi = 0;
        for (const h of hens) {
            if (gi === m) break;
            let r;
            if (grains[gi] >= h) {
                if (grains[gi] - h > T) return false;
                r = h + T;
            } else {
                const d = h - grains[gi];
                if (d > T) return false;
                r = h + Math.max(T - d, Math.floor((T - d) / 2));
            }
            while (gi < m && grains[gi] <= r) gi++;
        }
        return gi === m;
    };
    let lo = 0, hi = 2e9;
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (ok(mid)) hi = mid; else lo = mid + 1;
    }
    return lo;
};
